import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_packages(data):
    pkgs = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, tfm, pkg['id'])
                pkgs[key] = pkg['resolvedVersion']
    return pkgs

b = get_packages(baseline)
a = get_packages(after)

changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k, bv, av))

if changes:
    print('VERSION CHANGES:')
    for (proj, tfm, pkg), bv, av in changes:
        print(f'  {proj} ({tfm}) {pkg}: {bv} -> {av}')
else:
    print('No version changes detected - conversion is version-neutral for unchanged packages')

# Check specifically for the aligned packages
print()
print('ALIGNED PACKAGES (version raised to highest):')
for (proj, tfm, pkg), bv, av in changes:
    print(f'  {proj} ({tfm}) {pkg}: {bv} -> {av}')
"

